def ler(base, nome):
    with open(base + nome + '.csv', encoding='utf-8-sig') as f:
        return list(csv.DictReader(f, delimiter=';'))


for nome in ('comissoes_por_lojista', 'divergencias_taxa', 'notas_a_emitir', 'lancamentos_classificados', 'pendencias'):
    a = {r['id_saida']: r for r in ler(ANTES, nome)}
    b = {r['id_saida']: r for r in ler(REPO, nome)}
    cols_novas = sorted(set(next(iter(b.values())).keys()) - set(next(iter(a.values())).keys()))
    mud = collections.Counter()
    for i in set(a) & set(b):
        for c in a[i]:
            if a[i][c] != b[i].get(c):
                mud[c] += 1
    print(f"{nome}: antes {len(a)} depois {len(b)} | novos {sorted(set(b) - set(a))} | saíram {sorted(set(a) - set(b))} | "
          f"colunas novas {cols_novas} | campos alterados {dict(mud)}")

ra = collections.defaultdict(D); rb = collections.defaultdict(D)
for r in ler(ANTES, 'rastro'):
    ra[r['id_saida']] += D(r['valor'])
