      '| soma mudou', sorted(i for i in set(ra) & set(rb) if ra[i] != rb[i]))
lc_a = {r['id_saida']: r for r in ler(ANTES, 'lancamentos_classificados')}
lc_b = {r['id_saida']: r for r in ler(REPO, 'lancamentos_classificados')}
print('lançamentos com confiança alterada:', sorted((i.split('-')[-1], lc_a[i]['confianca'], lc_b[i]['confianca'])
                                                    for i in lc_a if lc_a[i]['confianca'] != lc_b[i]['confianca']))
print('lançamentos com conta alterada:', [i for i in lc_a if lc_a[i]['conta_codigo'] != lc_b[i]['conta_codigo']])

# formato nos seis arquivos
erros = []
for nome in ('comissoes_por_lojista', 'divergencias_taxa', 'notas_a_emitir', 'lancamentos_classificados', 'pendencias', 'rastro'):
    with open(REPO + nome + '.csv', encoding='utf-8-sig') as f:
        cab = f.readline()
    if ';' not in cab or ',' in cab:
        erros.append(f'{nome}: cabeçalho {cab!r}')
    for r in ler(REPO, nome):
        for c, v in r.items():
            if c in ('cnpj', 'tomador_cnpj') and v and not re.fullmatch(r'\d{14}', v):
                erros.append(f'{nome} {c}={v}')
            if c in ('valor', 'valor_brl', 'comissao_brl', 'diferenca_brl', 'valor_referencia_brl') and v and not re.fullmatch(r'-?\d+\.\d{2}', v):
                erros.append(f'{nome} {c}={v}')
            if c in ('data', 'data_decisao') and v and not re.fullmatch(r'\d{4}-\d{2}-\d{2}', v):
                erros.append(f'{nome} {c}={v}')
print('formato:', erros or 'ok (separador ;, decimal com ponto e 2 casas, datas ISO, CNPJ com 14 dígitos)')

